using System;
using System.Threading.Tasks;
using System.Runtime.InteropServices.JavaScript;
using ThreeDEngine.Core.Diagnostics;

namespace ThreeDEngine.Avalonia.WebGL.Interop;

internal static partial class WebGlInterop
{
    private const string EmbeddedModuleBase64 = "";
    private static bool _imported;
    private static Task? _importTask;
    private static readonly object ImportGate = new();

    public static Task EnsureImportedAsync()
    {
        lock (ImportGate)
        {
            if (_imported)
            {
                return Task.CompletedTask;
            }

            return _importTask ??= ImportWithRetryStateAsync();
        }
    }

    private static async Task ImportWithRetryStateAsync()
    {
        try
        {
            await ImportCoreAsync().ConfigureAwait(false);
            lock (ImportGate)
            {
                _imported = true;
            }
        }
        catch
        {
            // A failed Task must not poison all future presenter attachments. Clearing the
            // shared task makes a later attach perform a real import attempt again.
            lock (ImportGate)
            {
                if (!_imported)
                {
                    _importTask = null;
                }
            }

            throw;
        }
    }

    private static async Task ImportCoreAsync()
    {
        Exception? last = null;

        try
        {
            var dataUrl = "data:text/javascript;base64," + EmbeddedModuleBase64;
            await JSHost.ImportAsync("ThreeDEngineSceneKit", dataUrl).ConfigureAwait(false);
            EngineLog3D.Information("WebGL.Interop", "Embedded JavaScript module imported.");
            return;
        }
        catch (Exception ex)
        {
            last = ex;
            EngineLog3D.Warning("WebGL.Interop", "Embedded JavaScript module import failed; checking deployed module locations.", ex);
        }

        foreach (var path in new[]
                 {
                     "/3DEngine/mini3d.webgl.js",
                     "./3DEngine/mini3d.webgl.js",
                     "3DEngine/mini3d.webgl.js"
                 })
        {
            try
            {
                await JSHost.ImportAsync("ThreeDEngineSceneKit", path).ConfigureAwait(false);
                EngineLog3D.Information("WebGL.Interop", $"JavaScript module imported from '{path}'.");
                return;
            }
            catch (Exception ex)
            {
                last = ex;
            }
        }

        var failure = last ?? new InvalidOperationException("Unable to import 3DEngine WebGL module.");
        EngineLog3D.Critical("WebGL.Interop", "Unable to import the JavaScript module from any configured location.", failure);
        throw failure;
    }

